import{_ as a,a as s,c as o,ac as t}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第二册：实践与进步 · 综合复习与自测 · 第64–72课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第二册：实践与进步 · 综合复习与自测 · 第64–72课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-2/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 综合复习与自测 · 第55–63课","link":"/life/english/new-concept/book-2/review-part-07"},"next":{"text":"第二册：实践与进步 · 综合复习与自测 · 第73–81课","link":"/life/english/new-concept/book-2/review-part-09"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 综合复习与自测 · 第55–63课","link":"/life/english/new-concept/book-2/review-part-07"},"next":{"text":"第二册：实践与进步 · 综合复习与自测 · 第73–81课","link":"/life/english/new-concept/book-2/review-part-09"}},"headers":[],"relativePath":"life/english/new-concept/book-2/review-part-08.md","filePath":"life/english/new-concept/book-2/review-part-08.md"}'),n={name:"life/english/new-concept/book-2/review-part-08.md"};function r(l,e,i,h,d,p){return s(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="第二册-实践与进步-·-综合复习与自测-·-第64–72课" tabindex="-1">第二册：实践与进步 · 综合复习与自测 · 第64–72课 <a class="header-anchor" href="#第二册-实践与进步-·-综合复习与自测-·-第64–72课" aria-label="Permalink to &quot;第二册：实践与进步 · 综合复习与自测 · 第64–72课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/overview">本册介绍</a> · <a href="/life/english/new-concept/book-2/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-2/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-2/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-2/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-2/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-2/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-64-·-非真实条件句" tabindex="-1">Lesson 64 · 非真实条件句 <a class="header-anchor" href="#lesson-64-·-非真实条件句" aria-label="Permalink to &quot;Lesson 64 · 非真实条件句 {#lesson-64-·-非真实条件句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> If the earlier plan had succeeded, the route would have opened sooner.</p><h3 id="练习-1-63" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-63" aria-label="Permalink to &quot;练习 1 {#练习-1-63}&quot;">​</a></h3><p>填 succeed：If the plan had ___, the route would have opened sooner.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> succeeded</p><p><strong>解析：</strong> had 后要求过去分词。</p></details><p><strong>表达迁移：</strong> 写一个未实施方案的三句回顾，包括假设结果、实际障碍和后来变化。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>If the earlier plan had succeeded, the route would have opened sooner. However, funding was not available. A later team developed a different design.</p><p>第一句的组织方式：had succeeded 是过去反事实条件，would have opened 是未发生的假设结果，sooner 比较时间早晚。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：would have open 缺少过去分词；have 后应为 opened。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-064">回看本课</a></p><h2 id="lesson-65-·-动词、宾语与补足语" tabindex="-1">Lesson 65 · 动词、宾语与补足语 <a class="header-anchor" href="#lesson-65-·-动词、宾语与补足语" aria-label="Permalink to &quot;Lesson 65 · 动词、宾语与补足语 {#lesson-65-·-动词、宾语与补足语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The keeper made the elephant move towards a basket of fruit.</p><h3 id="练习-1-64" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-64" aria-label="Permalink to &quot;练习 1 {#练习-1-64}&quot;">​</a></h3><p>选 move/to move：The keeper made the elephant ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> move</p><p><strong>解析：</strong> make 的主动使役结构接原形。</p></details><p><strong>表达迁移：</strong> 描述一次非对抗方式解决阻塞的过程，避免夸大动物心理。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The keeper made the elephant move towards a basket of fruit. The road soon became clear. Nobody needed to shout at the animal.</p><p>第一句的组织方式：made 后接宾语 elephant，再用原形 move 作补足语；towards 只说明方向。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：made the elephant to move 在主动句中多余 to；被动才常用 was made to move。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-065">回看本课</a></p><h2 id="lesson-66-·-完成进行时与持续活动" tabindex="-1">Lesson 66 · 完成进行时与持续活动 <a class="header-anchor" href="#lesson-66-·-完成进行时与持续活动" aria-label="Permalink to &quot;Lesson 66 · 完成进行时与持续活动 {#lesson-66-·-完成进行时与持续活动}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> A jar of honey has been leaking inside the delivery van.</p><h3 id="练习-1-65" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-65" aria-label="Permalink to &quot;练习 1 {#练习-1-65}&quot;">​</a></h3><p>填 has/have：A jar of honey ___ been leaking.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> has</p><p><strong>解析：</strong> 主语核心 jar 是单数。</p></details><p><strong>表达迁移：</strong> 写一次根据气味或痕迹发现问题的过程，区分初步怀疑与最终发现。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A jar of honey has been leaking inside the delivery van. The driver first suspected the engine. He found the sticky trail beside a damaged box.</p><p>第一句的组织方式：A jar 为单数主语，has been leaking 表持续过程；of honey 说明内容物，inside 为地点。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：honey have been 错误；这里主语 a jar of honey 的核心是 jar，配 has。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-066">回看本课</a></p><h2 id="lesson-67-·-完成进行时与持续活动" tabindex="-1">Lesson 67 · 完成进行时与持续活动 <a class="header-anchor" href="#lesson-67-·-完成进行时与持续活动" aria-label="Permalink to &quot;Lesson 67 · 完成进行时与持续活动 {#lesson-67-·-完成进行时与持续活动}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The scientists have been monitoring the volcano since March.</p><h3 id="练习-1-66" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-66" aria-label="Permalink to &quot;练习 1 {#练习-1-66}&quot;">​</a></h3><p>选 since/for：They have been observing it ___ March.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> since</p><p><strong>解析：</strong> March 是时间起点。</p></details><p><strong>表达迁移：</strong> 写一段科学观察简报，给出监测时段、一项发现和仍不确定的信息。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The scientists have been monitoring the volcano since March. They have recorded a rise in ground temperature. The report does not give an exact eruption date.</p><p>第一句的组织方式：have been monitoring 是完成进行时，since March 给起点；scientists 是复数主语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：since three months 不合常用表达；用 for three months 或 since March。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-067">回看本课</a></p><h2 id="lesson-68-·-动名词与动词搭配" tabindex="-1">Lesson 68 · 动名词与动词搭配 <a class="header-anchor" href="#lesson-68-·-动名词与动词搭配" aria-label="Permalink to &quot;Lesson 68 · 动名词与动词搭配 {#lesson-68-·-动名词与动词搭配}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> My neighbour insisted on helping me carry the boxes.</p><h3 id="练习-1-67" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-67" aria-label="Permalink to &quot;练习 1 {#练习-1-67}&quot;">​</a></h3><p>填 help：She insisted on ___ me.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> helping</p><p><strong>解析：</strong> 介词 on 后接动名词。</p></details><p><strong>表达迁移：</strong> 写三句礼貌回应坚持帮忙的人：感谢、解释、替代安排。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>My neighbour insisted on helping me carry the boxes. I thanked her but explained that the boxes were empty. We agreed to meet for tea later.</p><p>第一句的组织方式：insisted on 是谓语搭配，helping 为介词宾语；help me carry 中 carry 可不带 to。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：insist to help 应改为 insist on helping；avoid to answer 应为 avoid answering。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-068">回看本课</a></p><h2 id="lesson-69-·-不定式与目的" tabindex="-1">Lesson 69 · 不定式与目的 <a class="header-anchor" href="#lesson-69-·-不定式与目的" aria-label="Permalink to &quot;Lesson 69 · 不定式与目的 {#lesson-69-·-不定式与目的}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The learner was told to stop beside the yellow line.</p><h3 id="练习-1-68" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-68" aria-label="Permalink to &quot;练习 1 {#练习-1-68}&quot;">​</a></h3><p>填 to/for：The learner was told ___ stop.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> tell somebody to do 的被动保留 to。</p></details><p><strong>表达迁移：</strong> 写一次操作失误复盘，交代指令、错误和纠正，不推断恶意。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The learner was told to stop beside the yellow line. She pressed the wrong pedal for a moment. The instructor used the dual controls and stopped the car.</p><p>第一句的组织方式：was told 是被动转述，to stop 是要求内容，beside the yellow line 为位置。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：brake 是刹车，break 是弄坏或休息；二者同音但拼写含义不同。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-069">回看本课</a></p><h2 id="lesson-70-·-分词修饰与逻辑主语" tabindex="-1">Lesson 70 · 分词修饰与逻辑主语 <a class="header-anchor" href="#lesson-70-·-分词修饰与逻辑主语" aria-label="Permalink to &quot;Lesson 70 · 分词修饰与逻辑主语 {#lesson-70-·-分词修饰与逻辑主语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Waving a red flag, the steward guided the visitors away.</p><h3 id="练习-1-69" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-69" aria-label="Permalink to &quot;练习 1 {#练习-1-69}&quot;">​</a></h3><p>谁在挥旗：Waving a flag, the steward opened the gate?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The steward.</p><p><strong>解析：</strong> 分词状语默认与主句主语同指。</p></details><p><strong>表达迁移：</strong> 写三句现场处置，使用一个与主句同主语的分词短语。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Waving a red flag, the steward guided the visitors away. A loose animal had entered the ring. Everyone waited behind the barrier until it was led out.</p><p>第一句的组织方式：Waving 的执行者是 the steward；guided 是主句过去式，the visitors 是宾语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：Waving a flag, the visitors were moved 会让逻辑主语变成游客，不一定符合想表达的意思。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-070">回看本课</a></p><h2 id="lesson-71-·-非真实条件句" tabindex="-1">Lesson 71 · 非真实条件句 <a class="header-anchor" href="#lesson-71-·-非真实条件句" aria-label="Permalink to &quot;Lesson 71 · 非真实条件句 {#lesson-71-·-非真实条件句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> If the clock had not been repaired, it would have stopped that winter.</p><h3 id="练习-1-70" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-70" aria-label="Permalink to &quot;练习 1 {#练习-1-70}&quot;">​</a></h3><p>补全：It would ___ stopped without repairs.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> have</p><p><strong>解析：</strong> 过去假设结果结构为 would have done。</p></details><p><strong>表达迁移：</strong> 写一个历史设施得到维护的故事，再补一句未维护的假设后果。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>If the clock had not been repaired, it would have stopped that winter. The town paid for the work in autumn. It still rings every evening.</p><p>第一句的组织方式：if 从句 had not been repaired 为过去完成被动；主句 would have stopped 表未发生的过去结果。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：would stopped 缺少 have；过去反事实结果要用 would have stopped。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-071">回看本课</a></p><h2 id="lesson-72-·-分词修饰与逻辑主语" tabindex="-1">Lesson 72 · 分词修饰与逻辑主语 <a class="header-anchor" href="#lesson-72-·-分词修饰与逻辑主语" aria-label="Permalink to &quot;Lesson 72 · 分词修饰与逻辑主语 {#lesson-72-·-分词修饰与逻辑主语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> A car called Silver Finch completed three test runs.</p><h3 id="练习-1-71" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-71" aria-label="Permalink to &quot;练习 1 {#练习-1-71}&quot;">​</a></h3><p>句中主句谓语是 called 还是 completed？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> completed</p><p><strong>解析：</strong> called 为后置定语，completed 承担主句谓语。</p></details><p><strong>表达迁移：</strong> 介绍一台自拟名称的测试设备，给出测试数量和下一步决定。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A car called Silver Finch completed three test runs. Its fastest run ended early because of a tyre problem. The team postponed the record attempt.</p><p>第一句的组织方式：called Silver Finch 修饰 A car，completed 才是主句谓语，three test runs 为宾语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：A car called Silver Finch. 只是名词短语，不构成完整陈述句。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-072">回看本课</a></p>',76)])])}const u=a(n,[["render",r]]);export{m as __pageData,u as default};
